// membase.h - header-only, read-only process memory access (Windows, C++17)
//
// Usage:
//   membase::Process proc(pid);                       // throws on failure
//   auto mod = proc.module(L"target.exe");             // std::optional<Module>
//   auto m   = proc.read_matrix(mod->base + MATRIX_OFFSET);
//   auto arr = proc.read_entries(mod->base + ENTRY_ARRAY_OFFSET);
//
// Offsets are configuration: define them below or pass them in at the call site.

#pragma once

#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#include <tlhelp32.h>

#include <array>
#include <cstddef>
#include <cstdint>
#include <cwchar>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <vector>

namespace membase {

// ---------------------------------------------------------------------------
// Configuration (fill in for your build)
// ---------------------------------------------------------------------------
inline constexpr std::uintptr_t MATRIX_OFFSET      = 0x0; // TODO: set
inline constexpr std::uintptr_t ENTRY_ARRAY_OFFSET = 0x0; // TODO: set
inline constexpr std::size_t    ENTRY_COUNT        = 64;
inline constexpr std::size_t    ENTRY_SIZE         = 0x1F0;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
struct Matrix4x4 {
    float m[4][4];
};
static_assert(sizeof(Matrix4x4) == 64, "Matrix4x4 must be 16 floats");

// Opaque entry; reinterpret fields with Entry::get<T>(offset).
struct Entry {
    std::array<std::uint8_t, ENTRY_SIZE> raw;

    template <typename T>
    T get(std::size_t offset) const {
        static_assert(std::is_trivially_copyable_v<T>, "T must be trivially copyable");
        if (offset + sizeof(T) > raw.size())
            throw std::out_of_range("membase::Entry::get offset out of range");
        T out;
        std::memcpy(&out, raw.data() + offset, sizeof(T));
        return out;
    }
};
static_assert(sizeof(Entry) == ENTRY_SIZE, "Entry size mismatch");

using EntryArray = std::array<Entry, ENTRY_COUNT>;

struct Module {
    std::wstring   name;
    std::wstring   path;
    std::uintptr_t base = 0;
    std::size_t    size = 0;
};

// ---------------------------------------------------------------------------
// RAII handle
// ---------------------------------------------------------------------------
class Handle {
public:
    Handle() = default;
    explicit Handle(HANDLE h) : h_(h) {}
    ~Handle() { reset(); }
    Handle(const Handle&) = delete;
    Handle& operator=(const Handle&) = delete;
    Handle(Handle&& o) noexcept : h_(o.h_) { o.h_ = nullptr; }
    Handle& operator=(Handle&& o) noexcept {
        if (this != &o) { reset(); h_ = o.h_; o.h_ = nullptr; }
        return *this;
    }
    HANDLE get() const { return h_; }
    bool valid() const { return h_ && h_ != INVALID_HANDLE_VALUE; }
    void reset() {
        if (valid()) CloseHandle(h_);
        h_ = nullptr;
    }
private:
    HANDLE h_ = nullptr;
};

// ---------------------------------------------------------------------------
// Process
// ---------------------------------------------------------------------------
class Process {
public:
    explicit Process(DWORD pid) : pid_(pid) {
        handle_ = Handle(OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_LIMITED_INFORMATION,
                                     FALSE, pid));
        if (!handle_.valid())
            throw std::runtime_error("OpenProcess failed, error " +
                                     std::to_string(GetLastError()));
        refresh_modules();
    }

    DWORD  pid() const { return pid_; }
    HANDLE handle() const { return handle_.get(); }
    const std::vector<Module>& modules() const { return modules_; }

    // Re-walk the module list (call again if the target loads modules later).
    void refresh_modules() {
        modules_.clear();

        Handle snap;
        // Snapshot can transiently fail with ERROR_BAD_LENGTH while the target is loading.
        for (int attempt = 0; attempt < 8; ++attempt) {
            snap = Handle(CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_));
            if (snap.valid()) break;
            if (GetLastError() != ERROR_BAD_LENGTH) break;
            Sleep(10);
        }
        if (!snap.valid())
            throw std::runtime_error("CreateToolhelp32Snapshot failed, error " +
                                     std::to_string(GetLastError()));

        MODULEENTRY32W me{};
        me.dwSize = sizeof(me);
        if (!Module32FirstW(snap.get(), &me)) return;
        do {
            Module m;
            m.name = me.szModule;
            m.path = me.szExePath;
            m.base = reinterpret_cast<std::uintptr_t>(me.modBaseAddr);
            m.size = static_cast<std::size_t>(me.modBaseSize);
            modules_.push_back(std::move(m));
        } while (Module32NextW(snap.get(), &me));
    }

    // Case-insensitive lookup by module file name (e.g. L"target.exe").
    std::optional<Module> module(std::wstring_view name) const {
        for (const auto& m : modules_) {
            if (m.name.size() == name.size() &&
                _wcsnicmp(m.name.c_str(), name.data(), name.size()) == 0)
                return m;
        }
        return std::nullopt;
    }

    // Main executable module (first entry in the snapshot).
    std::optional<Module> main_module() const {
        if (modules_.empty()) return std::nullopt;
        return modules_.front();
    }

    // Raw read; returns false on partial/failed read.
    bool read_raw(std::uintptr_t addr, void* out, std::size_t size) const {
        SIZE_T got = 0;
        if (!ReadProcessMemory(handle_.get(), reinterpret_cast<LPCVOID>(addr), out, size, &got))
            return false;
        return got == size;
    }

    template <typename T>
    std::optional<T> read(std::uintptr_t addr) const {
        static_assert(std::is_trivially_copyable_v<T>, "T must be trivially copyable");
        T out;
        if (!read_raw(addr, &out, sizeof(T))) return std::nullopt;
        return out;
    }

    // --- The two exposed reads -------------------------------------------

    std::optional<Matrix4x4> read_matrix(std::uintptr_t addr) const {
        return read<Matrix4x4>(addr);
    }

    // Reads ENTRY_COUNT contiguous ENTRY_SIZE-byte structs in one call.
    // Heap-allocated: 64 * 0x1F0 = ~31 KB, too large to want on the stack.
    std::optional<std::unique_ptr<EntryArray>> read_entries(std::uintptr_t addr) const {
        auto arr = std::make_unique<EntryArray>();
        if (!read_raw(addr, arr->data(), sizeof(EntryArray))) return std::nullopt;
        return arr;
    }

    // Convenience: module base + configured offsets.
    std::optional<Matrix4x4> read_matrix(const Module& mod,
                                         std::uintptr_t offset = MATRIX_OFFSET) const {
        return read_matrix(mod.base + offset);
    }
    std::optional<std::unique_ptr<EntryArray>> read_entries(
        const Module& mod, std::uintptr_t offset = ENTRY_ARRAY_OFFSET) const {
        return read_entries(mod.base + offset);
    }

private:
    DWORD               pid_;
    Handle              handle_;
    std::vector<Module> modules_;
};

} // namespace membase
